package com.iwms.report;

import com.iwms.model.BulkProduct;
import com.iwms.model.Category;
import com.iwms.model.Permission;
import com.iwms.model.Product;
import com.iwms.model.User;
import com.iwms.service.InventoryService;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Objects;

/**
 * CSV import and export utility for inventory catalog records.
 * Enforces field-level access control by redacting cost prices when generated by users without permission.
 */
public class CsvReportGenerator {

    private final InventoryService inventoryService;

    public CsvReportGenerator(InventoryService inventoryService) {
        this.inventoryService = Objects.requireNonNull(inventoryService, "inventoryService cannot be null");
    }

    /**
     * Exports current product catalog to CSV format.
     */
    public String exportProductsCsv(User requestingUser) {
        Objects.requireNonNull(requestingUser, "Requesting user cannot be null");

        boolean canViewCosts = requestingUser.hasPermission(Permission.VIEW_COST_PRICES);
        StringBuilder sb = new StringBuilder();

        // CSV Header
        sb.append("SKU,Name,Category,UnitPrice,CostPrice,MinStockLevel,CurrentStock\n");

        List<Product> products = inventoryService.getAllProducts();
        for (Product p : products) {
            String safeName = p.getName().contains(",") ? "\"" + p.getName() + "\"" : p.getName();
            String unitPriceStr = String.format(Locale.US, "%.2f", p.getUnitPrice());
            String costPriceStr = canViewCosts ? String.format(Locale.US, "%.2f", p.getCostPrice()) : "[REDACTED]";
            int currentStock = inventoryService.getCurrentStock(p.getSku());

            sb.append(p.getSku()).append(",")
                    .append(safeName).append(",")
                    .append(p.getCategory().name()).append(",")
                    .append(unitPriceStr).append(",")
                    .append(costPriceStr).append(",")
                    .append(p.getMinStockLevel()).append(",")
                    .append(currentStock).append("\n");
        }

        return sb.toString();
    }

    /**
     * Imports simple catalog items from CSV string.
     */
    public List<Product> parseProductsCsv(String csvContent) {
        if (csvContent == null || csvContent.isBlank()) {
            return List.of();
        }

        List<Product> list = new ArrayList<>();
        String[] lines = csvContent.split("\n");
        for (int i = 1; i < lines.length; i++) {
            String line = lines[i].trim();
            if (line.isBlank()) continue;

            String[] parts = line.split(",", -1);
            if (parts.length >= 6) {
                String sku = parts[0].trim();
                String name = parts[1].replace("\"", "").trim();
                Category category = Category.valueOf(parts[2].trim());
                double unitPrice = Double.parseDouble(parts[3].trim());
                double costPrice = parts[4].contains("REDACTED") ? 0.0 : Double.parseDouble(parts[4].trim());
                int minStock = Integer.parseInt(parts[5].trim());

                Product product = BulkProduct.builder()
                        .sku(sku)
                        .name(name)
                        .category(category)
                        .unitPrice(unitPrice)
                        .costPrice(costPrice)
                        .minStockLevel(minStock)
                        .build();

                list.add(product);
            }
        }
        return list;
    }
}
